3194	static void remind_tick(void)
3195	{
3196	  time_t now = mono_now();
3197	  int i;
3198	
3199	  if (g_eye_toast != NULL && now >= g_eye_toast_until)
3200	    {
3201	      lv_obj_delete(g_eye_toast);
3202	      g_eye_toast = NULL;
3203	    }
3204	
3205	  for (i = 0; i < REMIND_COUNT; i++)
3206	    {
3207	      struct remind_s *r = &g_remind[i];
3208	
3209	      if (!r->enabled || now < r->off_until || now < r->due)
3210	        {
3211	          continue;
3212	        }
3213	
3214	      if (r->ok_text == NULL)
3215	        {
3216	          /* 角标式提醒：已有卡片时也照出，二者不冲突 */
3217	
3218	          if (g_eye_toast == NULL)
3219	            {
3220	              eye_toast_show();
3221	            }
3222	
3223	          remind_reschedule(i, now);
3224	          continue;
3225	        }
3226	
3227	      /* 同一时间只出一张卡片，其余的到期了就排队等着 */
3228	
3229	      if (g_remind_active < 0)
3230	        {
3231	          remind_show(i);
3232	        }
3233	    }
3234	}
