3236	static void today_refresh(void)
3237	{
3238	  static const char *const week[] =
3239	  {
3240	    "日", "一", "二", "三", "四", "五", "六"
3241	  };
3242	
3243	  struct remind_s *sit = &g_remind[REMIND_SIT];
3244	  time_t now = mono_now();
3245	  time_t wall = time(NULL);
3246	  int mins = (int)((now - g_sit_start) / 60);
3247	  int pct;
3248	
3249	  if (wall_clock_synced())
3250	    {
3251	      time_t local = wall + UI_TZ_OFFSET_S;
3252	      struct tm tm;
3253	      long day = (long)(local / 86400);
3254	
3255	      gmtime_r(&local, &tm);
3256	      lv_label_set_text_fmt(g_today_clock, "%02d:%02d",
3257	                            tm.tm_hour, tm.tm_min);
3258	      lv_label_set_text_fmt(g_today_date, "%d月%d日  星期%s",
3259	                            tm.tm_mon + 1, tm.tm_mday, week[tm.tm_wday]);
3260	
3261	      if (day != g_water_day)
3262	        {
3263	          g_water_day = day;
3264	          g_water_count = 0;
3265	        }
3266	    }
3267	  else
3268	    {
3269	      lv_label_set_text(g_today_clock, "--:--");
3270	      lv_label_set_text(g_today_date, "时间未同步");
3271	    }
3272	
3273	  pct = mins * 100 / (sit->interval_min > 0 ? sit->interval_min : 1);
3274	  lv_arc_set_value(g_sit_arc, pct > 100 ? 100 : pct);
3275	  lv_obj_set_style_arc_color(g_sit_arc,
3276	                             lv_color_hex(pct >= 100 ? UI_BAD : UI_ACCENT),
3277	                             LV_PART_INDICATOR);
3278	  lv_label_set_text_fmt(g_sit_minutes, "%d\n分钟", mins);
3279	
3280	  if (!sit->enabled)
3281	    {
3282	      lv_label_set_text(g_sit_hint, "久坐提醒已关闭");
3283	    }
3284	  else if (now < sit->off_until)
3285	    {
3286	      lv_label_set_text(g_sit_hint, "今天不再提醒");
3287	    }
3288	  else if (now < sit->due)
3289	    {
3290	      lv_label_set_text_fmt(g_sit_hint, "%d 分钟后提醒起身",
3291	                            (int)((sit->due - now + 59) / 60));
3292	    }
3293	  else
3294	    {
3295	      lv_label_set_text(g_sit_hint, "该起来活动了");
3296	    }
3297	
3298	  lv_bar_set_value(g_water_bar,
3299	                   g_water_count > UI_WATER_GOAL ? UI_WATER_GOAL
3300	                                                 : g_water_count,
3301	                   LV_ANIM_OFF);
3302	  lv_label_set_text_fmt(g_water_label, "今天 %d / %d 杯",
3303	                        g_water_count, UI_WATER_GOAL);
3304	}
